25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream ethernet frame receiver (AXI in, Ethernet frame out)
33	 */
34	module eth_axis_rx #
35	(
36	    // Width of AXI stream interfaces in bits
37	    parameter DATA_WIDTH = 8,
38	    // Propagate tkeep signal
39	    // If disabled, tkeep assumed to be 1'b1
40	    parameter KEEP_ENABLE = (DATA_WIDTH>8),
41	    // tkeep signal width (words per cycle)
42	    parameter KEEP_WIDTH = (DATA_WIDTH/8)
43	)
44	(
45	    input  wire                  clk,
46	    input  wire                  rst,
47	
48	    /*
49	     * AXI input
50	     */
51	    input  wire [DATA_WIDTH-1:0] s_axis_tdata,
52	    input  wire [KEEP_WIDTH-1:0] s_axis_tkeep,
53	    input  wire                  s_axis_tvalid,
54	    output wire                  s_axis_tready,
55	    input  wire                  s_axis_tlast,
56	    input  wire                  s_axis_tuser,
57	
58	    /*
59	     * Ethernet frame output
60	     */
61	    output wire                  m_eth_hdr_valid,
62	    input  wire                  m_eth_hdr_ready,
63	    output wire [47:0]           m_eth_dest_mac,
64	    output wire [47:0]           m_eth_src_mac,
65	    output wire [15:0]           m_eth_type,
66	    output wire [DATA_WIDTH-1:0] m_eth_payload_axis_tdata,
67	    output wire [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep,
68	    output wire                  m_eth_payload_axis_tvalid,
69	    input  wire                  m_eth_payload_axis_tready,
70	    output wire                  m_eth_payload_axis_tlast,
71	    output wire                  m_eth_payload_axis_tuser,
72	
73	    /*
74	     * Status signals
75	     */
76	    output wire                  busy,
77	    output wire                  error_header_early_termination
78	);
79	
80	parameter BYTE_LANES = KEEP_ENABLE ? KEEP_WIDTH : 1;
81	
82	parameter HDR_SIZE = 14;
83	
84	parameter CYCLE_COUNT = (HDR_SIZE+BYTE_LANES-1)/BYTE_LANES;
85	
86	parameter PTR_WIDTH = $clog2(CYCLE_COUNT);
87	
88	parameter OFFSET = HDR_SIZE % BYTE_LANES;
89	
90	// bus width assertions
91	initial begin
92	    if (BYTE_LANES * 8 != DATA_WIDTH) begin
93	        $error("Error: AXI stream interface requires byte (8-bit) granularity (instance %m)");
94	        $finish;
95	    end
96	end
97	
98	/*
99	
100	Ethernet frame
101	
102	 Field                       Length
103	 Destination MAC address     6 octets
104	 Source MAC address          6 octets
105	 Ethertype                   2 octets
106	
107	This module receives an Ethernet frame on an AXI stream interface, decodes
108	and strips the headers, then produces the header fields in parallel along
109	with the payload in a separate AXI stream.
110	
111	*/
112	
113	reg read_eth_header_reg = 1'b1, read_eth_header_next;
114	reg read_eth_payload_reg = 1'b0, read_eth_payload_next;
115	reg [PTR_WIDTH-1:0] ptr_reg = 0, ptr_next;
116	
117	reg flush_save;
118	reg transfer_in_save;
119	
120	reg s_axis_tready_reg = 1'b0, s_axis_tready_next;
121	
122	reg m_eth_hdr_valid_reg = 1'b0, m_eth_hdr_valid_next;
123	reg [47:0] m_eth_dest_mac_reg = 48'd0, m_eth_dest_mac_next;
124	reg [47:0] m_eth_src_mac_reg = 48'd0, m_eth_src_mac_next;
125	reg [15:0] m_eth_type_reg = 16'd0, m_eth_type_next;
126	
127	reg busy_reg = 1'b0;
128	reg error_header_early_termination_reg = 1'b0, error_header_early_termination_next;
129	
130	reg [DATA_WIDTH-1:0] save_axis_tdata_reg = 64'd0;
131	reg [KEEP_WIDTH-1:0] save_axis_tkeep_reg = 8'd0;
132	reg save_axis_tlast_reg = 1'b0;
133	reg save_axis_tuser_reg = 1'b0;
134	
135	reg [DATA_WIDTH-1:0] shift_axis_tdata;
136	reg [KEEP_WIDTH-1:0] shift_axis_tkeep;
137	reg shift_axis_tvalid;
138	reg shift_axis_tlast;
139	reg shift_axis_tuser;
140	reg shift_axis_input_tready;
141	reg shift_axis_extra_cycle_reg = 1'b0;
142	
143	// internal datapath
144	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_int;
145	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_int;
146	reg                  m_eth_payload_axis_tvalid_int;
147	reg                  m_eth_payload_axis_tready_int_reg = 1'b0;
148	reg                  m_eth_payload_axis_tlast_int;
149	reg                  m_eth_payload_axis_tuser_int;
150	wire                 m_eth_payload_axis_tready_int_early;
151	
152	assign s_axis_tready = s_axis_tready_reg;
153	
154	assign m_eth_hdr_valid = m_eth_hdr_valid_reg;
155	assign m_eth_dest_mac = m_eth_dest_mac_reg;
156	assign m_eth_src_mac = m_eth_src_mac_reg;
157	assign m_eth_type = m_eth_type_reg;
158	
159	assign busy = busy_reg;
160	assign error_header_early_termination = error_header_early_termination_reg;
161	
162	always @* begin
163	    if (OFFSET == 0) begin
164	        // passthrough if no overlap
165	        shift_axis_tdata = s_axis_tdata;
166	        shift_axis_tkeep = s_axis_tkeep;
167	        shift_axis_tvalid = s_axis_tvalid;
168	        shift_axis_tlast = s_axis_tlast;
169	        shift_axis_tuser = s_axis_tuser;
170	        shift_axis_input_tready = 1'b1;
171	    end else if (shift_axis_extra_cycle_reg) begin
172	        shift_axis_tdata = {s_axis_tdata, save_axis_tdata_reg} >> (OFFSET*8);
173	        shift_axis_tkeep = {{KEEP_WIDTH{1'b0}}, save_axis_tkeep_reg} >> OFFSET;
174	        shift_axis_tvalid = 1'b1;
175	        shift_axis_tlast = save_axis_tlast_reg;
176	        shift_axis_tuser = save_axis_tuser_reg;
177	        shift_axis_input_tready = flush_save;
178	    end else begin
179	        shift_axis_tdata = {s_axis_tdata, save_axis_tdata_reg} >> (OFFSET*8);
180	        shift_axis_tkeep = {s_axis_tkeep, save_axis_tkeep_reg} >> OFFSET;
181	        shift_axis_tvalid = s_axis_tvalid;
182	        shift_axis_tlast = (s_axis_tlast && ((s_axis_tkeep & ({KEEP_WIDTH{1'b1}} << OFFSET)) == 0));
183	        shift_axis_tuser = (s_axis_tuser && ((s_axis_tkeep & ({KEEP_WIDTH{1'b1}} << OFFSET)) == 0));
184	        shift_axis_input_tready = !(s_axis_tlast && s_axis_tready && s_axis_tvalid);
185	    end
186	end
187	
188	always @* begin
189	    read_eth_header_next = read_eth_header_reg;
190	    read_eth_payload_next = read_eth_payload_reg;
191	    ptr_next = ptr_reg;
192	
193	    s_axis_tready_next = m_eth_payload_axis_tready_int_early && shift_axis_input_tready && (!m_eth_hdr_valid || m_eth_hdr_ready);
194	
195	    flush_save = 1'b0;
196	    transfer_in_save = 1'b0;
197	
198	    m_eth_hdr_valid_next = m_eth_hdr_valid_reg && !m_eth_hdr_ready;
199	
200	    m_eth_dest_mac_next = m_eth_dest_mac_reg;
201	    m_eth_src_mac_next = m_eth_src_mac_reg;
202	    m_eth_type_next = m_eth_type_reg;
203	
204	    error_header_early_termination_next = 1'b0;
205	
206	    m_eth_payload_axis_tdata_int = shift_axis_tdata;
207	    m_eth_payload_axis_tkeep_int = shift_axis_tkeep;
208	    m_eth_payload_axis_tvalid_int = 1'b0;
209	    m_eth_payload_axis_tlast_int = shift_axis_tlast;
210	    m_eth_payload_axis_tuser_int = shift_axis_tuser;
211	
212	    if ((s_axis_tready && s_axis_tvalid) || (m_eth_payload_axis_tready_int_reg && shift_axis_extra_cycle_reg)) begin
213	        transfer_in_save = 1'b1;
214	
215	        if (read_eth_header_reg) begin
216	            // word transfer in - store it
217	            ptr_next = ptr_reg + 1;
218	
219	            `define _HEADER_FIELD_(offset, field) \
220	                if (ptr_reg == offset/BYTE_LANES && (!KEEP_ENABLE || s_axis_tkeep[offset%BYTE_LANES])) begin \
221	                    field = s_axis_tdata[(offset%BYTE_LANES)*8 +: 8]; \
222	                end
223	
224	            `_HEADER_FIELD_(0,  m_eth_dest_mac_next[5*8 +: 8])
225	            `_HEADER_FIELD_(1,  m_eth_dest_mac_next[4*8 +: 8])
226	            `_HEADER_FIELD_(2,  m_eth_dest_mac_next[3*8 +: 8])
227	            `_HEADER_FIELD_(3,  m_eth_dest_mac_next[2*8 +: 8])
228	            `_HEADER_FIELD_(4,  m_eth_dest_mac_next[1*8 +: 8])
229	            `_HEADER_FIELD_(5,  m_eth_dest_mac_next[0*8 +: 8])
230	            `_HEADER_FIELD_(6,  m_eth_src_mac_next[5*8 +: 8])
231	            `_HEADER_FIELD_(7,  m_eth_src_mac_next[4*8 +: 8])
232	            `_HEADER_FIELD_(8,  m_eth_src_mac_next[3*8 +: 8])
233	            `_HEADER_FIELD_(9,  m_eth_src_mac_next[2*8 +: 8])
234	            `_HEADER_FIELD_(10, m_eth_src_mac_next[1*8 +: 8])
235	            `_HEADER_FIELD_(11, m_eth_src_mac_next[0*8 +: 8])
236	            `_HEADER_FIELD_(12, m_eth_type_next[1*8 +: 8])
237	            `_HEADER_FIELD_(13, m_eth_type_next[0*8 +: 8])
238	
239	            if (ptr_reg == 13/BYTE_LANES && (!KEEP_ENABLE || s_axis_tkeep[13%BYTE_LANES])) begin
240	                if (!shift_axis_tlast) begin
241	                    m_eth_hdr_valid_next = 1'b1;
242	                    read_eth_header_next = 1'b0;
243	                    read_eth_payload_next = 1'b1;
244	                end
245	            end
246	
247	            `undef _HEADER_FIELD_
248	        end
249	
250	        if (read_eth_payload_reg) begin
251	            // transfer payload
252	            m_eth_payload_axis_tdata_int = shift_axis_tdata;
253	            m_eth_payload_axis_tkeep_int = shift_axis_tkeep;
254	            m_eth_payload_axis_tvalid_int = 1'b1;
255	            m_eth_payload_axis_tlast_int = shift_axis_tlast;
256	            m_eth_payload_axis_tuser_int = shift_axis_tuser;
257	        end
258	
259	        if (shift_axis_tlast) begin
260	            if (read_eth_header_next) begin
261	                // don't have the whole header
262	                error_header_early_termination_next = 1'b1;
263	            end
264	
265	            flush_save = 1'b1;
266	            ptr_next = 1'b0;
267	            read_eth_header_next = 1'b1;
268	            read_eth_payload_next = 1'b0;
269	        end
270	    end
271	end
272	
273	always @(posedge clk) begin
274	    read_eth_header_reg <= read_eth_header_next;
275	    read_eth_payload_reg <= read_eth_payload_next;
276	    ptr_reg <= ptr_next;
277	
278	    s_axis_tready_reg <= s_axis_tready_next;
279	
280	    m_eth_hdr_valid_reg <= m_eth_hdr_valid_next;
281	    m_eth_dest_mac_reg <= m_eth_dest_mac_next;
282	    m_eth_src_mac_reg <= m_eth_src_mac_next;
283	    m_eth_type_reg <= m_eth_type_next;
284	
285	    error_header_early_termination_reg <= error_header_early_termination_next;
286	
287	    busy_reg <= (read_eth_payload_next || ptr_next != 0);
288	
289	    if (transfer_in_save) begin
290	        save_axis_tdata_reg <= s_axis_tdata;
291	        save_axis_tkeep_reg <= s_axis_tkeep;
292	        save_axis_tuser_reg <= s_axis_tuser;
293	    end
294	
295	    if (flush_save) begin
296	        save_axis_tlast_reg <= 1'b0;
297	        shift_axis_extra_cycle_reg <= 1'b0;
298	    end else if (transfer_in_save) begin
299	        save_axis_tlast_reg <= s_axis_tlast;
300	        shift_axis_extra_cycle_reg <= OFFSET ? s_axis_tlast && ((s_axis_tkeep & ({KEEP_WIDTH{1'b1}} << OFFSET)) != 0) : 1'b0;
301	    end
302	
303	    if (rst) begin
304	        read_eth_header_reg <= 1'b1;
305	        read_eth_payload_reg <= 1'b0;
306	        ptr_reg <= 0;
307	        s_axis_tready_reg <= 1'b0;
308	        m_eth_hdr_valid_reg <= 1'b0;
309	        save_axis_tlast_reg <= 1'b0;
310	        shift_axis_extra_cycle_reg <= 1'b0;
311	        busy_reg <= 1'b0;
312	        error_header_early_termination_reg <= 1'b0;
313	    end
314	end
315	
316	// output datapath logic
317	reg [DATA_WIDTH-1:0] m_eth_payload_axis_tdata_reg = {DATA_WIDTH{1'b0}};
318	reg [KEEP_WIDTH-1:0] m_eth_payload_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
319	reg                  m_eth_payload_axis_tvalid_reg = 1'b0, m_eth_payload_axis_tvalid_next;
320	reg                  m_eth_payload_axis_tlast_reg = 1'b0;
321	reg                  m_eth_payload_axis_tuser_reg = 1'b0;
322	
323	reg [DATA_WIDTH-1:0] temp_m_eth_payload_axis_tdata_reg = {DATA_WIDTH{1'b0}};
324	reg [KEEP_WIDTH-1:0] temp_m_eth_payload_axis_tkeep_reg = {KEEP_WIDTH{1'b0}};
325	reg                  temp_m_eth_payload_axis_tvalid_reg = 1'b0, temp_m_eth_payload_axis_tvalid_next;
326	reg                  temp_m_eth_payload_axis_tlast_reg = 1'b0;
327	reg                  temp_m_eth_payload_axis_tuser_reg = 1'b0;
328	
329	// datapath control
330	reg store_eth_payload_int_to_output;
331	reg store_eth_payload_int_to_temp;
332	reg store_eth_payload_axis_temp_to_output;
333	
334	assign m_eth_payload_axis_tdata = m_eth_payload_axis_tdata_reg;
335	assign m_eth_payload_axis_tkeep = KEEP_ENABLE ? m_eth_payload_axis_tkeep_reg : {KEEP_WIDTH{1'b1}};
336	assign m_eth_payload_axis_tvalid = m_eth_payload_axis_tvalid_reg;
337	assign m_eth_payload_axis_tlast = m_eth_payload_axis_tlast_reg;
338	assign m_eth_payload_axis_tuser = m_eth_payload_axis_tuser_reg;
339	
340	// enable ready input next cycle if output is ready or if both output registers are empty
341	assign m_eth_payload_axis_tready_int_early = m_eth_payload_axis_tready || (!temp_m_eth_payload_axis_tvalid_reg && !m_eth_payload_axis_tvalid_reg);
342	
343	always @* begin
344	    // transfer sink ready state to source
345	    m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_reg;
346	    temp_m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
347	
348	    store_eth_payload_int_to_output = 1'b0;
349	    store_eth_payload_int_to_temp = 1'b0;
350	    store_eth_payload_axis_temp_to_output = 1'b0;
351	    
352	    if (m_eth_payload_axis_tready_int_reg) begin
353	        // input is ready
354	        if (m_eth_payload_axis_tready || !m_eth_payload_axis_tvalid_reg) begin
355	            // output is ready or currently not valid, transfer data to output
356	            m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
357	            store_eth_payload_int_to_output = 1'b1;
358	        end else begin
359	            // output is not ready, store input in temp
360	            temp_m_eth_payload_axis_tvalid_next = m_eth_payload_axis_tvalid_int;
361	            store_eth_payload_int_to_temp = 1'b1;
362	        end
363	    end else if (m_eth_payload_axis_tready) begin
364	        // input is not ready, but output is ready
365	        m_eth_payload_axis_tvalid_next = temp_m_eth_payload_axis_tvalid_reg;
366	        temp_m_eth_payload_axis_tvalid_next = 1'b0;
367	        store_eth_payload_axis_temp_to_output = 1'b1;
368	    end
369	end
370	
371	always @(posedge clk) begin
372	    m_eth_payload_axis_tvalid_reg <= m_eth_payload_axis_tvalid_next;
373	    m_eth_payload_axis_tready_int_reg <= m_eth_payload_axis_tready_int_early;
374	    temp_m_eth_payload_axis_tvalid_reg <= temp_m_eth_payload_axis_tvalid_next;
375	
376	    // datapath
377	    if (store_eth_payload_int_to_output) begin
378	        m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
379	        m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
380	        m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
381	        m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
382	    end else if (store_eth_payload_axis_temp_to_output) begin
383	        m_eth_payload_axis_tdata_reg <= temp_m_eth_payload_axis_tdata_reg;
384	        m_eth_payload_axis_tkeep_reg <= temp_m_eth_payload_axis_tkeep_reg;
385	        m_eth_payload_axis_tlast_reg <= temp_m_eth_payload_axis_tlast_reg;
386	        m_eth_payload_axis_tuser_reg <= temp_m_eth_payload_axis_tuser_reg;
387	    end
388	
389	    if (store_eth_payload_int_to_temp) begin
390	        temp_m_eth_payload_axis_tdata_reg <= m_eth_payload_axis_tdata_int;
391	        temp_m_eth_payload_axis_tkeep_reg <= m_eth_payload_axis_tkeep_int;
392	        temp_m_eth_payload_axis_tlast_reg <= m_eth_payload_axis_tlast_int;
393	        temp_m_eth_payload_axis_tuser_reg <= m_eth_payload_axis_tuser_int;
394	    end
395	
396	    if (rst) begin
397	        m_eth_payload_axis_tvalid_reg <= 1'b0;
398	        m_eth_payload_axis_tready_int_reg <= 1'b0;
399	        temp_m_eth_payload_axis_tvalid_reg <= 1'b0;
400	    end
401	end
402	
403	endmodule
404	
405	`resetall
406

