25	// Language: Verilog 2001
26	
27	`resetall
28	`timescale 1ns / 1ps
29	`default_nettype none
30	
31	/*
32	 * AXI4-Stream GMII frame receiver (GMII in, AXI out)
33	 */
34	module axis_gmii_rx #
35	(
36	    parameter DATA_WIDTH = 8,
37	    parameter PTP_TS_ENABLE = 0,
38	    parameter PTP_TS_WIDTH = 96,
39	    parameter USER_WIDTH = (PTP_TS_ENABLE ? PTP_TS_WIDTH : 0) + 1
40	)
41	(
42	    input  wire                     clk,
43	    input  wire                     rst,
44	
45	    /*
46	     * GMII input
47	     */
48	    input  wire [DATA_WIDTH-1:0]    gmii_rxd,
49	    input  wire                     gmii_rx_dv,
50	    input  wire                     gmii_rx_er,
51	
52	    /*
53	     * AXI output
54	     */
55	    output wire [DATA_WIDTH-1:0]    m_axis_tdata,
56	    output wire                     m_axis_tvalid,
57	    output wire                     m_axis_tlast,
58	    output wire [USER_WIDTH-1:0]    m_axis_tuser,
59	
60	    /*
61	     * PTP
62	     */
63	    input  wire [PTP_TS_WIDTH-1:0]  ptp_ts,
64	
65	    /*
66	     * Control
67	     */
68	    input  wire                     clk_enable,
69	    input  wire                     mii_select,
70	
71	    /*
72	     * Configuration
73	     */
74	    input  wire                     cfg_rx_enable,
75	
76	    /*
77	     * Status
78	     */
79	    output wire                     start_packet,
80	    output wire                     error_bad_frame,
81	    output wire                     error_bad_fcs
82	);
83	
84	// bus width assertions
85	initial begin
86	    if (DATA_WIDTH != 8) begin
87	        $error("Error: Interface width must be 8");
88	        $finish;
89	    end
90	end
91	
92	localparam [7:0]
93	    ETH_PRE = 8'h55,
94	    ETH_SFD = 8'hD5;
95	
96	localparam [2:0]
97	    STATE_IDLE = 3'd0,
98	    STATE_PAYLOAD = 3'd1,
99	    STATE_WAIT_LAST = 3'd2;
100	
101	reg [2:0] state_reg = STATE_IDLE, state_next;
102	
103	// datapath control signals
104	reg reset_crc;
105	reg update_crc;
106	
107	reg mii_odd = 1'b0;
108	reg in_frame = 1'b0;
109	
110	reg [DATA_WIDTH-1:0] gmii_rxd_d0 = {DATA_WIDTH{1'b0}};
111	reg [DATA_WIDTH-1:0] gmii_rxd_d1 = {DATA_WIDTH{1'b0}};
112	reg [DATA_WIDTH-1:0] gmii_rxd_d2 = {DATA_WIDTH{1'b0}};
113	reg [DATA_WIDTH-1:0] gmii_rxd_d3 = {DATA_WIDTH{1'b0}};
114	reg [DATA_WIDTH-1:0] gmii_rxd_d4 = {DATA_WIDTH{1'b0}};
115	
116	reg gmii_rx_dv_d0 = 1'b0;
117	reg gmii_rx_dv_d1 = 1'b0;
118	reg gmii_rx_dv_d2 = 1'b0;
119	reg gmii_rx_dv_d3 = 1'b0;
120	reg gmii_rx_dv_d4 = 1'b0;
121	
122	reg gmii_rx_er_d0 = 1'b0;
123	reg gmii_rx_er_d1 = 1'b0;
124	reg gmii_rx_er_d2 = 1'b0;
125	reg gmii_rx_er_d3 = 1'b0;
126	reg gmii_rx_er_d4 = 1'b0;
127	
128	reg [DATA_WIDTH-1:0] m_axis_tdata_reg = {DATA_WIDTH{1'b0}}, m_axis_tdata_next;
129	reg m_axis_tvalid_reg = 1'b0, m_axis_tvalid_next;
130	reg m_axis_tlast_reg = 1'b0, m_axis_tlast_next;
131	reg m_axis_tuser_reg = 1'b0, m_axis_tuser_next;
132	
133	reg start_packet_int_reg = 1'b0;
134	reg start_packet_reg = 1'b0;
135	reg error_bad_frame_reg = 1'b0, error_bad_frame_next;
136	reg error_bad_fcs_reg = 1'b0, error_bad_fcs_next;
137	
138	reg [PTP_TS_WIDTH-1:0] ptp_ts_reg = 0;
139	
140	reg [31:0] crc_state = 32'hFFFFFFFF;
141	wire [31:0] crc_next;
142	
143	assign m_axis_tdata = m_axis_tdata_reg;
144	assign m_axis_tvalid = m_axis_tvalid_reg;
145	assign m_axis_tlast = m_axis_tlast_reg;
146	assign m_axis_tuser = PTP_TS_ENABLE ? {ptp_ts_reg, m_axis_tuser_reg} : m_axis_tuser_reg;
147	
148	assign start_packet = start_packet_reg;
149	assign error_bad_frame = error_bad_frame_reg;
150	assign error_bad_fcs = error_bad_fcs_reg;
151	
152	lfsr #(
153	    .LFSR_WIDTH(32),
154	    .LFSR_POLY(32'h4c11db7),
155	    .LFSR_CONFIG("GALOIS"),
156	    .LFSR_FEED_FORWARD(0),
157	    .REVERSE(1),
158	    .DATA_WIDTH(8),
159	    .STYLE("AUTO")
160	)
161	eth_crc_8 (
162	    .data_in(gmii_rxd_d4),
163	    .state_in(crc_state),
164	    .data_out(),
165	    .state_out(crc_next)
166	);
167	
168	always @* begin
169	    state_next = STATE_IDLE;
170	
171	    reset_crc = 1'b0;
172	    update_crc = 1'b0;
173	
174	    m_axis_tdata_next = {DATA_WIDTH{1'b0}};
175	    m_axis_tvalid_next = 1'b0;
176	    m_axis_tlast_next = 1'b0;
177	    m_axis_tuser_next = 1'b0;
178	
179	    error_bad_frame_next = 1'b0;
180	    error_bad_fcs_next = 1'b0;
181	
182	    if (!clk_enable) begin
183	        // clock disabled - hold state
184	        state_next = state_reg;
185	    end else if (mii_select && !mii_odd) begin
186	        // MII even cycle - hold state
187	        state_next = state_reg;
188	    end else begin
189	        case (state_reg)
190	            STATE_IDLE: begin
191	                // idle state - wait for packet
192	                reset_crc = 1'b1;
193	
194	                if (gmii_rx_dv_d4 && !gmii_rx_er_d4 && gmii_rxd_d4 == ETH_SFD && cfg_rx_enable) begin
195	                    state_next = STATE_PAYLOAD;
196	                end else begin
197	                    state_next = STATE_IDLE;
198	                end
199	            end
200	            STATE_PAYLOAD: begin
201	                // read payload
202	                update_crc = 1'b1;
203	
204	                m_axis_tdata_next = gmii_rxd_d4;
205	                m_axis_tvalid_next = 1'b1;
206	
207	                if (gmii_rx_dv_d4 && gmii_rx_er_d4) begin
208	                    // error
209	                    m_axis_tlast_next = 1'b1;
210	                    m_axis_tuser_next = 1'b1;
211	                    error_bad_frame_next = 1'b1;
212	                    state_next = STATE_WAIT_LAST;
213	                end else if (!gmii_rx_dv) begin
214	                    // end of packet
215	                    m_axis_tlast_next = 1'b1;
216	                    if (gmii_rx_er_d0 || gmii_rx_er_d1 || gmii_rx_er_d2 || gmii_rx_er_d3) begin
217	                        // error received in FCS bytes
218	                        m_axis_tuser_next = 1'b1;
219	                        error_bad_frame_next = 1'b1;
220	                    end else if ({gmii_rxd_d0, gmii_rxd_d1, gmii_rxd_d2, gmii_rxd_d3} == ~crc_next) begin
221	                        // FCS good
222	                        m_axis_tuser_next = 1'b0;
223	                    end else begin
224	                        // FCS bad
225	                        m_axis_tuser_next = 1'b1;
226	                        error_bad_frame_next = 1'b1;
227	                        error_bad_fcs_next = 1'b1;
228	                    end
229	                    state_next = STATE_IDLE;
230	                end else begin
231	                    state_next = STATE_PAYLOAD;
232	                end
233	            end
234	            STATE_WAIT_LAST: begin
235	                // wait for end of packet
236	
237	                if (~gmii_rx_dv) begin
238	                    state_next = STATE_IDLE;
239	                end else begin
240	                    state_next = STATE_WAIT_LAST;
241	                end
242	            end
243	        endcase
244	    end
245	end
246	
247	always @(posedge clk) begin
248	    state_reg <= state_next;
249	
250	    m_axis_tdata_reg <= m_axis_tdata_next;
251	    m_axis_tvalid_reg <= m_axis_tvalid_next;
252	    m_axis_tlast_reg <= m_axis_tlast_next;
253	    m_axis_tuser_reg <= m_axis_tuser_next;
254	
255	    start_packet_int_reg <= 1'b0;
256	    start_packet_reg <= 1'b0;
257	
258	    if (start_packet_int_reg) begin
