284	                gmii_rx_dv_d1 <= gmii_rx_dv_d0 & gmii_rx_dv;
285	                gmii_rx_dv_d2 <= gmii_rx_dv_d1 & gmii_rx_dv;
286	                gmii_rx_dv_d3 <= gmii_rx_dv_d2 & gmii_rx_dv;
287	                gmii_rx_dv_d4 <= gmii_rx_dv_d3 & gmii_rx_dv;
288	
289	                gmii_rx_er_d0 <= gmii_rx_er | gmii_rx_er_d0;
